class Solution {
    private int find(int[] p, int x){ while(p[x]!=x){p[x]=p[p[x]];x=p[x];} return x; }
    public int numberOfComponents(int[][] properties, int k) {
        int n = properties.length; int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = i;
        Set<Integer>[] s = new HashSet[n];
        for (int i = 0; i < n; i++) s[i] = new HashSet<>();
        for (int i = 0; i < n; i++) for (int v : properties[i]) s[i].add(v);
        for (int i = 0; i < n; i++)
            for (int j = i+1; j < n; j++) {
                int inter = 0;
                for (int v : s[i]) if (s[j].contains(v)) inter++;
                if (inter >= k) p[find(p, i)] = find(p, j);
            }
        Set<Integer> r = new HashSet<>();
        for (int i = 0; i < n; i++) r.add(find(p, i));
        return r.size();
    }
}

