var numberOfComponents = function(properties, k) {
    const n = properties.length;
    const sets = properties.map(p => new Set(p));
    const par = Array.from({length: n}, (_, i) => i);
    const find = x => { while (par[x] !== x) { par[x] = par[par[x]]; x = par[x]; } return x; };
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++) {
            let inter = 0;
            for (const v of sets[i]) if (sets[j].has(v)) inter++;
            if (inter >= k) par[find(i)] = find(j);
        }
    return new Set(Array.from({length: n}, (_, i) => find(i))).size;
};
